def compute(vars):
    approved_options = vars["v1"]
    total_options = vars["v2"]

    if total_options == 0:
        return None

    percentage = approved_options / total_options * 100

    return {
        "value": percentage,
        "trace": {
            "approved_options": approved_options,
            "total_options": total_options,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
